public class Product {
    private final double price;
    public Product(double price) { this.price = price; }
    public double finalPrice() { return price; }
}

public class DiscountProduct extends Product {
    private final double rate;
    public DiscountProduct(double price, double rate) {
        super(price);
        this.rate = rate;
    }
    @Override
    public double finalPrice() { return super.finalPrice() * rate; }
}
```
